# --- 테스트에 주석이 필요하면 ---

@Test
void test5() {
    // 골드 등급(2)으로 10000원을 주문하면
    // 10% 할인이 적용되어 9000원이 된다
    assertThat(DiscountCalculator.calculate(10000, 2)).isEqualTo(9000);
}

#   주석 두 줄이 이름 한 줄로 대체된다

@Test
void 골드_회원은_10퍼센트_할인을_받는다() {
    assertThat(DiscountCalculator.calculate(10000, 2)).isEqualTo(9000);
}

